// Validate review-quality input. Products must already be verified (source_url present).
const i = $input.first().json;
if (!i.procurement_id) throw new Error('Missing procurement_id');
const products = Array.isArray(i.products) ? i.products : [];
for (const p of products) if (!p.source_url) throw new Error('Unverified product: ' + (p.product_id ?? '?'));
return [{ json: { procurement_id: i.procurement_id, trace_id: i.trace_id, products, spec_fields: i.spec_fields ?? ['processor','ram','storage','operating_system','display','battery','graphics'], review_evidence: i.review_evidence ?? {} } }];

// DETERMINISTIC evidence assessment (works without LLM; canonical libs: tools/_lib/source_quality.js, tools/_lib/evidence.js).
// Source tiers: manufacturer 1.0 / major retailer 0.9 / specialist 0.8 / publication 0.6 / video 0.4 / social 0.3 / unknown 0.3.
const inp = $input.first().json;
const TIERS = [
  { tier: 'HIGH', score: 1.0, domains: ['dell.com','hp.com','lenovo.com','asus.com','acer.com','apple.com','samsung.com','msi.com'] },
  { tier: 'HIGH', score: 0.9, domains: ['costco.com','walmart.com','bestbuy.com','croma.com','vijaysales.com','reliancedigital.in','dellstore.com'] },
  { tier: 'MEDIUM', score: 0.8, domains: ['91mobiles.com','91laptop.com','gsmarena.com','notebookcheck.net','rtings.com','tomshardware.com'] },
  { tier: 'MEDIUM', score: 0.6, domains: ['hindustantimes.com','yahoo.com','businessinsider.com','ndtv.com','gadgets360.com'] },
  { tier: 'MEDIUM', score: 0.4, domains: ['youtube.com','youtu.be','reddit.com'] },
  { tier: 'LOW', score: 0.3, domains: ['instagram.com','facebook.com','twitter.com','x.com','tiktok.com'] },
];
const classify = (url) => { const hm0 = /^https?:\/\/([^\/\s?#]+)/i.exec(String(url || '').trim()); const h = hm0 ? hm0[1].toLowerCase() : ''; if (!h) return { tier: 'LOW', score: 0.3 }; for (const t of TIERS) if (t.domains.some((d) => h.includes(d))) return { tier: t.tier, score: t.score }; return { tier: 'LOW', score: 0.3 }; };
const verified = (v) => v !== null && v !== undefined && !(typeof v === 'string' && (v.trim().toLowerCase() === 'unavailable' || v.trim() === '')) && !(typeof v === 'object' && Object.keys(v).length === 0);
const now = new Date().toISOString();
const evals = inp.products.map((p) => {
  const sq = classify(p.source_url);
  const specs = p.specifications && typeof p.specifications === 'object' ? p.specifications : {};
  const lower = Object.fromEntries(Object.entries(specs).map(([k, v]) => [k.toLowerCase(), v]));
  const total = inp.spec_fields.length;
  const nver = total ? inp.spec_fields.filter((f) => verified(lower[String(f).toLowerCase()])).length : 0;
  const rev = (inp.review_evidence && inp.review_evidence[p.product_id]) || {};
  const hasRating = typeof rev.rating === 'number' && rev.rating >= 0 && rev.rating <= (rev.scale ?? 5);
  return {
    procurement_id: inp.procurement_id, product_id: p.product_id,
    source_quality: sq.tier, source_quality_score: sq.score,
    specification_completeness: total ? nver / total : 0, spec_fields_total: total, spec_fields_verified: nver,
    review_rating: hasRating ? rev.rating : 'unavailable', review_scale: hasRating ? (rev.scale ?? 5) : null,
    review_count: Number.isInteger(rev.count) && rev.count >= 0 ? rev.count : 'unavailable',
    review_evidence: rev.snippet ?? 'unavailable',
    quality_evidence: [{ kind: 'source_classification', tier: sq.tier }, { kind: 'spec_completeness', verified: nver, total }],
    quality_confidence: sq.score >= 0.8 ? 0.8 : sq.score,
    source_urls: [p.source_url].concat(rev.urls ?? []),
    retrieved_at: now, data_status: nver === 0 && !hasRating ? 'PARTIAL' : 'PARTIAL',
  };
});
return [{ json: { procurement_id: inp.procurement_id, evaluations: evals, data_status: evals.length ? 'PARTIAL' : 'UNAVAILABLE' } }];

// Enforce quality-evaluation schema: URL present, tier valid, no invented ratings.
const out = $input.first().json;
const evals = Array.isArray(out.evaluations) ? out.evaluations : [];
for (const e of evals) {
  if (!['HIGH','MEDIUM','LOW'].includes(e.source_quality)) throw new Error('bad tier: ' + e.product_id);
  if (!(e.source_quality_score >= 0 && e.source_quality_score <= 1)) throw new Error('bad tier score: ' + e.product_id);
  if (typeof e.review_rating === 'number' && !(e.review_rating >= 0)) throw new Error('bad rating: ' + e.product_id);
  if (!Array.isArray(e.source_urls) || !e.source_urls.length) throw new Error('missing source_urls: ' + e.product_id);
}
return [{ json: { procurement_id: out.procurement_id, evaluations: evals, data_status: evals.length ? 'PARTIAL' : 'UNAVAILABLE' } }];
